const cutoff = Date.parse("2026-06-01T00:00:00Z");
const all: any[] = [];
for (let page = 1; page <= 50; page++) {
  const res: any = await tools.list_issues({ repo: "acme/api", state: "open", label: "bug", page });
  const items = Array.isArray(res) ? res : (res?.items ?? res?.issues ?? []);
  if (!items || items.length === 0) break;
  all.push(...items);
  if (items.length < 50) break;
}
const matches: number[] = [];
for (const it of all) {
  const n = it.number ?? it.iid;
  const d: any = await tools.get_issue({ repo: "acme/api", number: n });
  const labels = (d.labels ?? []).map((l: any) => (typeof l === "string" ? l : l.name));
  const ok =
    d.state === "open" &&
    labels.includes("bug") &&
    (d.milestone === null || d.milestone === undefined) &&
    typeof d.updated_at === "string" &&
    Date.parse(d.updated_at) < cutoff;
  if (ok) matches.push(d.number ?? d.iid ?? n);
}
const unique = [...new Set(matches)].sort((a, b) => a - b);
const applied: number[] = [];
const failed: { number: number; error: string }[] = [];
for (const n of unique) {
  try {
    await tools.add_label({ repo: "acme/api", number: n, label: "stale" });
    applied.push(n);
  } catch (e: any) {
    failed.push({ number: n, error: String(e?.message ?? e) });
  }
}
console.log(JSON.stringify({ listed: all.length, matched: unique.length, applied: applied.length, failed }));
console.log(unique.join(","));
return { listed: all.length, matched: unique.length, applied: applied.length, failed, numbers: unique };
